import java.util.*;

// Tracks which sessions are subscribed to which channels and fans out a
// new message to every currently connected subscriber in real time.
public class ChannelPubSubRouter {
    private final Map<String, Set<String>> channelToSessions = new HashMap<>(); // channelId -> connected session ids

    public void subscribe(String channelId, String sessionId) {
        channelToSessions.computeIfAbsent(channelId, k -> new HashSet<>()).add(sessionId); // register a subscriber
    }

    public void unsubscribe(String channelId, String sessionId) {
        Set<String> sessions = channelToSessions.get(channelId); // look up subscribers
        if (sessions != null) sessions.remove(sessionId);          // drop this session if present
    }

    public Set<String> publish(String channelId, String messageId, GatewayClient gateway) {
        Set<String> sessions = channelToSessions.getOrDefault(channelId, Collections.emptySet()); // who is listening
        for (String sessionId : sessions) {                                                          // push to each
            gateway.push(sessionId, messageId);
        }
        return sessions; // hand back who received it, for logging or testing
    }

    public interface GatewayClient {
        void push(String sessionId, String messageId);
    }
}

