import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

// Tracks a single last-read watermark per user per channel, letting any of
// a user's devices compute an unread count without per-message bookkeeping.
public class ReadCursorService {
    private final Map<String, Integer> cursors = new ConcurrentHashMap<>(); // "userId|channelId" -> last read sequence number

    public void advanceCursor(String userId, String channelId, int upToSequenceNumber) {
        String key = userId + "|" + channelId;                       // composite key for this user and channel
        cursors.merge(key, upToSequenceNumber, Math::max);              // only ever move the cursor forward, never backward
    }

    public int getCursor(String userId, String channelId) {
        return cursors.getOrDefault(userId + "|" + channelId, 0);      // 0 means nothing read yet
    }

    public int unreadCount(String userId, String channelId, int latestSequenceNumberInChannel) {
        int lastRead = getCursor(userId, channelId);                    // where this user last left off
        return Math.max(0, latestSequenceNumberInChannel-lastRead);      // everything after that is unread
    }
}

