import java.util.*;

// A simplified inverted index: maps each word to the set of message ids
// containing it, letting a keyword search find matching messages quickly.
public class SearchIndexer {
    private final Map<String, Set<String>> invertedIndex = new HashMap<>(); // word -> message ids containing it

    public void indexMessage(String messageId, String text) {
        for (String word : tokenize(text)) {                                  // split into searchable terms
            invertedIndex.computeIfAbsent(word, k -> new HashSet<>()).add(messageId); // record this message under the word
        }
    }

    public Set<String> search(String query) {
        Set<String> results = null;                                            // accumulator, null means not started
        for (String word : tokenize(query)) {                                     // every query term must match
            Set<String> matches = invertedIndex.getOrDefault(word, Collections.emptySet());
            if (results == null) {
                results = new HashSet<>(matches);                                    // first term seeds the result set
            } else {
                results.retainAll(matches);                                            // intersect with subsequent terms
            }
        }
        return results == null ? Collections.emptySet() : results; // messages containing every query term
    }

    private List<String> tokenize(String text) {
        List<String> words = new ArrayList<>();                        // collected lowercase words
        for (String raw : text.toLowerCase().split("\\s+")) {           // split on whitespace
            if (!raw.isEmpty()) words.add(raw);                            // skip empty fragments
        }
        return words; // simplified tokenization, a real system would strip punctuation and stem words too
    }
}

