#include <algorithm>
#include <iterator>
#include <map>
#include <set>
#include <sstream>
#include <string>
#include <vector>

// A simplified inverted index: maps each word to the set of message ids
// containing it, letting a keyword search find matching messages quickly.
class SearchIndexer {
public:
    void indexMessage(const std::string& messageId, const std::string& text) {
        for (auto& word : tokenize(text))                                     // split into searchable terms
            invertedIndex_[word].insert(messageId);                              // record this message under the word
    }

    std::set<std::string> search(const std::string& query) {
        std::set<std::string> results;
        bool started = false;                                                 // accumulator started flag
        for (auto& word : tokenize(query)) {                                      // every query term must match
            auto it = invertedIndex_.find(word);
            std::set<std::string> matches = it != invertedIndex_.end() ? it->second : std::set<std::string>();
            if (!started) {
                results = matches;                                                      // first term seeds the result set
                started = true;
            } else {
                std::set<std::string> intersected;
                std::set_intersection(results.begin(), results.end(), matches.begin(), matches.end(),
                                       std::inserter(intersected, intersected.begin()));
                results = intersected;                                                     // intersect with subsequent terms
            }
        }
        return results;   // messages containing every query term
    }

private:
    std::vector<std::string> tokenize(const std::string& text) {
        std::vector<std::string> words;                                    // collected lowercase words
        std::string lower = text;
        std::transform(lower.begin(), lower.end(), lower.begin(), ::tolower);
        std::istringstream iss(lower);
        std::string raw;
        while (iss >> raw) words.push_back(raw);                               // split on whitespace, skip empties
        return words;   // simplified tokenization, a real system would strip punctuation and stem words too
    }

    std::map<std::string, std::set<std::string>> invertedIndex_;   // word -> message ids containing it
};

